      "한 학생이 들어올 때만 수업 전체가 끊기는 경우는 공개 안내에 따로 정리돼 있지 않아요. 다만 무대(스테이지)에 올라온 사람이 많을수록 화면이 복잡해지고 네트워크 부담도 커진다고 나와 있어서, 그 학생의 영상·소리가 모두에게 전달되는 상태라면 그 학생 쪽 네트워크나 기기가 영향을 줄 수 있어요.\n\n시험해 볼 것\n1. 그 학생을 무대에서 내리거나 카메라를 끄고 들어오게 해 봅니다. 그래도 끊기는지 봅니다.\n2. 그 학생에게 공유기 가까이 가거나 휴대폰 핫스팟으로 들어오게 하고, 클래스인을 최신 버전으로 업데이트하게 합니다.\n3. 그 학생이 같은 계정으로 두 기기에 로그인하지 않았는지 봅니다. 한 계정은 수업에 기기 1대로만 들어가요.\n4. 관리자는 [수업 모니터링]에서 그 학생의 접속 기기 정보를 볼 수 있어요.",
