      "1) 녹화에 남았는지: 수업 녹화는 칠판·자료·교실 화면 같은 클래스인 화면을 녹화해요. 녹화 중에 화면 공유로 띄웠다면 은행 앱이 녹화본에 남았을 수 있다고 보셔야 해요. 학습 보고서의 Highlights(수업 화면을 1분마다 저장한 이미지)와 관리자용 교실 스크린샷에도 찍혔을 수 있어요.\n2) 그 부분만 지우기: 녹화본에서 한 구간만 잘라 지우는 기능은 공개 안내에 나와 있지 않아요. 관리자는 [스토리지] > [수업 리소스]에서 그 수업의 녹화본과 스크린샷을 확인하고 내려받거나 지울 수 있어요. 원본을 내려받아 그 부분을 잘라 낸 편집본을 [녹화된 수업 비디오]에 올리고 원본은 지우는 방법도 있어요.\n3) 매니저도 보는지: 공개 안내 기준으로 녹화본은 학원 관리자나 권한을 받은 계정이 확인하고 내려받을 수 있어요. 학생이 다시보기로 볼 수 있는지는 학원 설정에 따라 달라요.",
