    en: "That's scary—let's act fast. If you shared the bank app while recording, it may be in the recording, and also in the learning report's Highlights (a classroom screenshot saved every minute) and the admin's classroom screenshots. Our public guide shows no way to cut just one part of a recording; admins can view, download or delete a class's recording and screenshots in [스토리지] > [수업 리소스], and can upload an edited copy (with that part cut) to [녹화된 수업 비디오] after deleting the original. Admins (managers) can see recordings, so tell your academy manager right now and ask them to stop the replay or delete that recording and screenshots. Consider calling your bank too, and don't type your account number here.",
