      "1) 계정을 그대로 넘길지: 비밀번호만 바꿔 넘기기보다 후임 실장님 계정을 따로 두시는 게 안전해요. 공개 안내 기준으로 관리자 대시보드 [계정 정보] > [권한 관리] > [하위 계정 추가]에서 후임자 휴대폰 번호나 이메일로 하위 계정을 만들고 필요한 메뉴 권한을 주면 돼요. 쓰시던 계정이 하위 계정이면 인수인계가 끝난 뒤 같은 메뉴에서 [삭제]해요. 다만 쓰시던 계정이 결제할 때 로그인한 메인 관리자 계정이라면, 공개 안내상 결제할 때 로그인한 아이디가 그대로 메인 관리자 계정이 돼요. 메인 관리자를 다른 사람으로 바꾸는 방법은 공개 안내에 없어서 원장님과 함께 아래 [실시간 상담 연결]로 확인하세요.\n2) 개인 휴대폰 번호 정리: 계정에 연결된 번호를 바꾸는 방법은 공개 안내에 없어요. 로그인 아이디를 이메일과 휴대폰 번호 사이에서 바꿀 수도 없고, 꼭 바꾸려면 탈퇴한 뒤 새로 가입해야 해요. 일반 계정은 휴대폰이나 태블릿 클래스인 앱 [계정 및 보안]에서 본인 인증을 거쳐 지워요(PC에는 메뉴가 없어요). 다만 학원 관리자 계정으로 바뀐 계정은 바로 삭제되지 않고 별도 절차가 있어 상담 채널로 요청해야 해요. 지운 계정은 되돌리기 어려우니 학원 자료와 기록을 넘긴 뒤에 하세요.",
