      "1) 특정 시청자만 채팅 막기·내보내기: 공개 안내에 나와 있지 않아요.\n2) 올라온 메시지 지우기와 플레이백 반영: 메시지를 지우는 방법은 공개 안내에 없어요. 공개 안내에는 시청자 채팅은 강사가 교실 안 [수업 도구] > [실시간 채팅]에서 보고, 이 채팅 창은 교실 학생에게는 보이지 않고 녹화에도 남지 않는다고 나와 있어요. 플레이백 화면에 채팅이 따로 보이는지는 공개 안내에 없어요. 끝난 뒤에는 [관리] > [웹 라이브 및 다시 보기 관리]에서 참여자, 채팅, 시청 데이터를 볼 수 있어요.\n3) 미리 걸어 둘 예방 설정: 승인 뒤 공개하는 방식은 공개 안내에 없어요. 대신 웹 라이브 설정에서 ClassIn 계정 로그인 필요, 시청 비밀번호, 비로그인 사용자의 채팅 허용 여부, 시청 권한(링크를 받은 누구나 또는 선택한 인원만)을 정할 수 있고, 이 권한은 관리자 대시보드에서 바꿔요.",
