      "1) 체험 수업에 한 번 들어온 학생이 요금 학생 수에 들어가는지: 공개 안내에는 요금이 계정 수를 기준으로 하고, 강사·운영 계정이 몇 개 필요한지 세어 보라고 나와 있어요. 학생 수가 요금 구간에 들어가는지, 체험 학생이 포함되는지는 공개 안내에 없어서 단정하지 않을게요.\n2) 명단에서 지운 뒤 반영 시점: 이것도 공개 안내에 없어요. 요금제와 계약마다 다를 수 있어요.",
