      "1) 관리자 화면에서 수업별·참여자별 네트워크 지표(packet loss, jitter, RTT, 재접속 횟수) 사후 조회: 그런 지표 화면은 공개 안내에 나와 있지 않아요. 공개 안내로 확인되는 건 이 정도예요.\n- 수업 중 교실 상태 표시줄 왼쪽에 네트워크 상태가 보여요. 공개 가이드 화면 캡처에는 지연(ms)과 손실률이 함께 표시돼 있어요.\n- 진행 중인 수업은 [관리자 기능] > [수업 모니터링]에서 참여자의 접속 기기 정보를 봐요.\n- 끝난 수업은 [기관 관리] > [수업 관리] > [조작] 열 [관리] > [수업 모니터링 데이터]에서 교사·학생의 입장·퇴장 시간줄과 시간대별 학생 수 도표를 봐요. 시간줄의 표시에 마우스를 올리면 입장·퇴장 시각, 접속 기기, 나간 이유가 나와서 재접속도 이걸로 가늠할 수 있어요.\n2) 같은 지표를 API로 받기: 공개 안내에는 API로 계정 생성과 관리, 수업 개설, 수업 입장, 스케줄 관리를 연결하고 데이터 구독, 코스·수업 정보 조회도 있다고 나와 있지만, 네트워크 품질 지표 API는 나와 있지 않아요.\n3) 보관 기간: 공개 안내에 없어요.",
