      "1) 칠판이 USB 실물화상기를 카메라로 인식하는지, 그 위에 판서하는지: 공개 안내에는 교실 도구에 '보조 카메라(듀얼 POV)'가 있어, 보조 카메라를 연결하면 실물 교구나 손동작을 별도 화면으로 비춘다고 나와 있어요. 교재 페이지나 공책을 비추려는 용도에는 이 도구가 가장 가까워요. 다만 USB 실물화상기를 이 보조 카메라로 쓸 수 있는지(모델 호환)와 그 화면 위에 바로 판서할 수 있는지는 공개 안내에 없어요. 그 밖에 공개 안내로 확인되는 건 칠판에 연결한 웹캠이나 외장 카메라를 현장 녹화 카메라로 고른다는 것, 수업에 쓸 카메라·마이크는 입장 직전 [장비 테스트] 화면에서 고른다는 것이에요. 교실에 보이는 도구는 학원의 교실 스위치 설정에 따라 다를 수 있어요.\n2) 현장 녹화와 온라인 학생 화면에 들어가는지: 공개 안내에는 수업 녹화가 판서와 띄운 자료가 보이는 교실 화면을 그대로 녹화하고, 교실에서 카메라를 켰다면 화면 속 카메라 영역도 같이 찍힌다고 나와 있어요. 현장 녹화는 기기에 연결한 웹캠·외장 카메라가 찍는 모습을 별도 영상으로 남겨요. 그래서 실물화상기가 카메라로 잡혀 수업 화면에 보이면 함께 남을 가능성이 있지만, 단정하지는 않을게요.",
